*{
    padding: 0;
    margin: 0;
    line-height: 1.5;
}
header{
    background-color: rgb(0, 213, 255);
    height: 100px;
    position: fixed;
    width: 100%;
    display: flex;
    justify-content: space-between;
    opacity: 0.8;
    border-radius: 0 0 20px 0;
}
header img{
    height: 100%;
}
header nav ul li a{
    color: white;
    text-decoration: none;
    font-weight: bold;
}
header nav li {
    display: inline-block;
    padding: 20px;
}
h1{
    padding-top: 15px;
    color: rgb(255, 255, 255);
    transition: 2s;
    text-shadow: 2px 2px 30px black;
}
h1:hover{
    transform: scale(1.5) skew(30deg,0deg);
    opacity: 0.5;
    color: blue;
    margin-top: 40px;
}
main{
    padding-top: 120px;
    display: flex;
    justify-content: space-between;
    height: 640px;
    background-image: url(files/ap.png);
    background-repeat: no-repeat;
    background-size: cover;
}
section{
    width: 80%;
}
main nav{
    width: 20%;
}
main nav ul{
    padding-left: 20px;
    
}
main nav li{
    display: block;
    margin: 20px;
}
main nav a{
    color: gray;
    text-decoration: none;
}
iframe{
    width: 100%;
    height: 100%;
}
footer{
    border-top: 10px solid aqua;
    text-align: center;
    border-radius: 20px 0 0 0;
    background-color: rgb(255, 255, 255);
    height: 100px;
}
footer img{
    width: 40px;
    opacity: 0.5;
    transition: opacity 1s;
    padding: 20px 30px;

}
footer img:hover{
    opacity: 1;
}
#body_acc{
    padding-left: 30px;
}
p{
    text-align: justify;
}
ol li{
    list-style-type: upper-roman;
}
ol ul li{
    list-style-image: url(files/puces.png);
}
video{
    display: block;
    margin: auto;
}
.largeur{
    display: inline-block;
    width: 200px;
    }
    
.largeur1{
    width: 200px;
    display: inline-block;
    text-align: end;
    }

.bt{
    border: 1px solid rgb(78, 172, 221);
    padding: 0 10px;
    font-size: 1.2em;
    border-radius: 5px;
    cursor: pointer;
    }
.centrer{
    text-align: center;
}

#command{
    display: flex;
    justify-content: space-between;
}
.ordinateur{
    width: 50%;
}
.img:hover{
    filter: invert(10);
}
table,th,td{
    border: 1px solid black;
    width: 600px;
    margin: auto;
    text-align: center;

}
#facture{
    width: 100%;
}

